// Following-camera runner. World depth is projected into a three-lane street.
const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');
let mode=0,distance=0,last=0,elapsed=0,paused=false,playing=false,jump=0,vy=0,objects=[],spawn=0,invincible=0,toastUntil=0,stroke=0,sound=true,audio,raf,lane=1,visualLane=1,rain=0,flood=0,rainCue=false,rainStart=-1,pressure=.3,noiseGain;
const meme=new Audio('assets/rain-meme.mp3');meme.preload='auto';
let clipBuffer,clipSource,clipStarted=0,clipOffset=0;
const clipBytes=fetch('assets/rain-meme.mp3').then(r=>r.arrayBuffer()).catch(()=>null);
function stopClip(){if(clipSource){clipOffset+=audio.currentTime-clipStarted;clipSource.stop();clipSource=null}meme.pause()}
function playClip(){if(!sound)return;if(clipBuffer&&audio){if(clipOffset>=clipBuffer.duration)return;clipSource=audio.createBufferSource();clipSource.buffer=clipBuffer;clipSource.connect(audio.destination);clipStarted=audio.currentTime;clipSource.start(0,clipOffset)}else meme.play().catch(()=>{})}
function beep(f=440,t=.08){if(!sound)return;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=f;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+t);o.start();o.stop(audio.currentTime+t)}
function rainAudio(){if(!audio||noiseGain)return;const b=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;const s=audio.createBufferSource(),f=audio.createBiquadFilter();s.buffer=b;s.loop=true;f.type='lowpass';f.frequency.value=1200;noiseGain=audio.createGain();noiseGain.gain.value=0;s.connect(f);f.connect(noiseGain);noiseGain.connect(audio.destination);s.start()}
$('sound').textContent='Âm thanh: bật ♫';$('sound').onclick=()=>{sound=!sound;$('sound').textContent=`Âm thanh: ${sound?'bật':'tắt'} ♫`;meme.muted=!sound;if(!sound)stopClip();beep()};
function toast(t,s=3){$('bubble').textContent=t;toastUntil=elapsed+s;$('bubble').hidden=false}
function resize(){const r=canvas.getBoundingClientRect();canvas.width=r.width*devicePixelRatio;canvas.height=r.height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}addEventListener('resize',resize);
function move(d){if(!playing||paused)return;lane=Math.max(0,Math.min(2,lane+d));beep(260+lane*70,.04)}
function act(){if(!playing||paused)return;if(mode===1){stroke=Math.min(1,stroke+.3);beep(330)}else if(jump===0){vy=400;jump=.01;beep(520)}}
$('action').onclick=act;$('left').onclick=()=>move(-1);$('right').onclick=()=>move(1);
let pointer;canvas.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointerup',e=>{if(!pointer)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.abs(dx)>25&&Math.abs(dx)>Math.abs(dy))move(Math.sign(dx));else if(dy< -25||Math.abs(dx)<25)act();pointer=null});canvas.addEventListener('pointercancel',()=>pointer=null);
addEventListener('keydown',e=>{if(!playing||!['Space','ArrowUp','ArrowLeft','ArrowRight','KeyA','KeyD'].includes(e.code))return;e.preventDefault();if(e.repeat)return;if(['ArrowLeft','KeyA'].includes(e.code))move(-1);else if(['ArrowRight','KeyD'].includes(e.code))move(1);else act()});
$('pause').onclick=()=>{if(!playing)return;paused=!paused;$('pause').textContent=paused?'Tiếp tục ▶':'Tạm dừng Ⅱ';if(paused)stopClip();else if(rainCue)playClip();$('pauseOverlay').hidden=!paused};
function start(){cancelAnimationFrame(raf);$('intro').hidden=true;$('finish').hidden=true;$('game').hidden=false;$('gift').hidden=true;$('openGift').hidden=false;$('checklist').hidden=true;mode=0;distance=elapsed=jump=vy=spawn=invincible=stroke=rain=flood=0;lane=visualLane=1;pressure=.3;rainCue=false;rainStart=-1;objects=[];playing=true;paused=false;last=0;meme.pause();meme.currentTime=0;meme.muted=!sound;beep(330);rainAudio();$('pauseOverlay').hidden=true;$('pause').textContent='Tạm dừng Ⅱ';setChapter();resize();toast('“Em giải thích thêm phần này được không?” — Lần này xin phép chạy.',4);raf=requestAnimationFrame(frame);window.scrollTo({top:0,behavior:'smooth'})}
$('start').onclick=()=>{start();prepareClip()};$('replay').onclick=()=>{stopClip();clipOffset=0;start();prepareClip()};
function prepareClip(){if(!audio||clipBuffer)return;clipBytes.then(b=>b&&audio.decodeAudioData(b.slice(0))).then(b=>{clipBuffer=b}).catch(()=>{})}
function setChapter(){const names=['Chạy đi Vy. Cuộc họp đang đuổi tới!','Đường chạy đã thành đường thủy.','Rạp phim phía trước. Đừng quay đầu!'];$('chapter').textContent=`CHƯƠNG 0${mode+1} / THE BIRTHDAY ESCAPE`;$('chapterTitle').textContent=names[mode];$('action').textContent=mode===1?'Chèo ≋':'Nhảy ↑';$('instruction').textContent=mode===1?'Vuốt trái/phải để lái · Chạm để chèo':'Vuốt trái/phải để đổi làn · Vuốt lên để nhảy'}
function triggerRain(){rainCue=true;toast('“Hồi chiều trời mưa…”',4);rainStart=elapsed+1.5;playClip()}
function frame(t){if(!playing)return;const dt=last?Math.min((t-last)/1000,.04):0;last=t;if(!paused){elapsed+=dt;distance+=dt*(mode===1?23+stroke*12:27);visualLane+=(lane-visualLane)*Math.min(1,dt*13);stroke=Math.max(0,stroke-dt*.3);invincible=Math.max(0,invincible-dt);pressure=Math.max(.15,pressure-dt*.018);if(jump>0){jump+=vy*dt;vy-=1000*dt;if(jump<=0)jump=vy=0}if(distance>=390&&!rainCue)triggerRain();if(rainStart>=0&&elapsed>=rainStart&&distance<1190)rain=Math.min(1,rain+dt*.22);if(distance>490&&distance<1100)flood=Math.min(1,flood+dt*.15);if(distance>=620&&mode===0){mode=1;objects=[];setChapter();toast('Đã nhận thuyền PHƯƠNG ÁN B. Mái chèo: “Kế hoạch đã chỉnh sửa”.',5)}if(distance>=1170&&mode===1){mode=2;objects=[];setChapter();toast('Đã lên bờ. Răng khôn chọn đúng lúc để gây chuyện.',4)}if(mode===2){rain=Math.max(0,rain-dt*.12);flood=Math.max(0,flood-dt*.3)}spawn-=dt;if(spawn<=0){const l=Math.floor(Math.random()*3);objects.push({z:1,lane:l,type:Math.floor(Math.random()*3),hit:false});if(Math.random()<.25)objects.push({z:1,lane:(l+1)%3,type:1,hit:false});spawn=1.25+Math.random()*.55}objects.forEach(o=>{o.z-=dt*.24;if(!o.hit&&o.z<.105){o.hit=true;if(o.lane===lane&&(mode===1||jump<48)&&invincible===0){invincible=1.2;pressure=Math.min(.88,pressure+.25);beep(140,.15);toast(mode===2?'Tên là khôn. Thời điểm xuất hiện thì cần xem lại.':'Vấp thôi, không cần làm slide giải trình. Chạy tiếp!')}else if(o.lane===lane)beep(690,.05)}});objects=objects.filter(o=>o.z>-.13);if(elapsed>toastUntil)$('bubble').hidden=true;if(distance>=1710){distance=1710;finish();return}}
if(noiseGain)noiseGain.gain.value=sound&&!paused?rain*.055:0;draw();$('distance').textContent=Math.floor(distance).toLocaleString('vi-VN')+' m';$('progress').style.width=distance/1710*100+'%';$('threat').textContent=pressure>.55?'Đang tới sát!':'Vẫn đang đuổi theo';raf=requestAnimationFrame(frame)}
function poly(p,c){ctx.fillStyle=c;ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();ctx.fill()}
function project(l,z,w,h){const p=Math.pow(Math.max(0,1-z),2);return{x:w/2+(l-1)*w*.265*p,y:h*.3+h*.65*p,s:.12+p*1.1,p}}
function text(t,x,y,s,c='#f4eadb'){ctx.fillStyle=c;ctx.font=`600 ${s}px "Be Vietnam Pro",sans-serif`;ctx.textAlign='center';ctx.fillText(t,x,y)}
function runner(x,y,s=1,chaser=false){ctx.save();ctx.translate(x,y);ctx.scale(s,s);const swing=Math.sin(elapsed*14)*14;ctx.lineCap='round';ctx.strokeStyle=chaser?'#314450':'#ecc9ac';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(-10,-40);ctx.lineTo(-13+swing*.3,-19);ctx.moveTo(10,-40);ctx.lineTo(13-swing*.3,-19);ctx.stroke();ctx.strokeStyle='#182530';ctx.lineWidth=11;ctx.beginPath();ctx.moveTo(-7,-17);ctx.lineTo(-10+swing*.6,8);ctx.moveTo(7,-17);ctx.lineTo(10-swing*.6,8);ctx.stroke();ctx.strokeStyle=chaser?'#dc7a67':'#efe6ce';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-10+swing*.6,9);ctx.lineTo(-17+swing*.6,11);ctx.moveTo(10-swing*.6,9);ctx.lineTo(17-swing*.6,11);ctx.stroke();ctx.fillStyle=chaser?'#b64e49':'#d9a363';ctx.fillRect(-15,-53,30,37);ctx.fillStyle=chaser?'#25323d':'#302d31';ctx.beginPath();ctx.arc(0,-65,15,0,7);ctx.fill();if(!chaser){ctx.beginPath();ctx.ellipse(9,-51,7,16,-.25,0,7);ctx.fill();text('VY',0,-30,8,'#28343d')}ctx.restore()}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,hy=h*.3;ctx.clearRect(0,0,w,h);let g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,rain>.4?'#172b3a':'#192d44');g.addColorStop(.7,'#576f76');g.addColorStop(1,'#172d3a');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.globalAlpha=1-rain*.8;ctx.fillStyle='#e8d3a7';ctx.beginPath();ctx.arc(w*.76,h*.13,23,0,7);ctx.fill();ctx.globalAlpha=1;
for(let side of [-1,1])for(let i=9;i>=0;i--){const z=(i/10+elapsed*.055)%1,p=(1-z)**2,x=w/2+side*(w*.12+w*.55*p),bw=18+65*p,bh=35+210*p;ctx.fillStyle=i%2?'#203c4b':'#182f40';ctx.fillRect(side<0?x-bw:x,hy+h*.65*p-bh,bw,bh);ctx.fillStyle='#e8bd7866';for(let a=0;a<3;a++)for(let b=0;b<5;b++)ctx.fillRect((side<0?x-bw:x)+5+a*bw/3,hy+h*.65*p-bh+12+b*bh/6,3+4*p,5+6*p)}
poly([[w*.44,hy],[w*.56,hy],[w*1.05,h],[w*-.05,h]],'#263c47');ctx.globalAlpha=flood*.85;poly([[w*.44,hy],[w*.56,hy],[w*1.05,h],[w*-.05,h]],'#29667a');ctx.globalAlpha=1;
for(let edge of [-1,1]){ctx.strokeStyle='#d4ad7266';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(w/2+edge*w*.06,hy);ctx.lineTo(w/2+edge*w*.55,h);ctx.stroke()}
for(let i=0;i<20;i++){const z=(i/20+elapsed*.24)%1,p=project(1,z,w,h);for(let line of [-.5,.5]){const q=project(1+line,z,w,h),r=project(1+line,Math.max(0,z-.025),w,h);ctx.strokeStyle=flood>.4?'#a9d6d34a':'#f2decf7a';ctx.lineWidth=1+p.p*3;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(r.x,r.y);ctx.stroke()}if(flood>.1){ctx.strokeStyle='#aedcda55';ctx.beginPath();ctx.moveTo(p.x-w*.3*p.p,p.y);ctx.lineTo(p.x+w*.3*p.p,p.y);ctx.stroke()}}
for(let i=0;i<3;i++){const x=w*(.15+i*.35),y=h+70-pressure*90+Math.sin(elapsed*5+i)*4;runner(x,y,.85,true);ctx.fillStyle='#a84845';ctx.fillRect(x-43,y-101,86,20);text(['DEADLINE','DỰ ÁN','CUỘC HỌP'][i],x,y-87,9)}
for(const o of [...objects].sort((a,b)=>b.z-a.z)){if(o.z<0)continue;const p=project(o.lane,o.z,w,h);ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.s,p.s);ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(0,0,33,9,0,0,7);ctx.fill();if(mode===2&&o.type!==2){ctx.font='49px "Segoe UI Emoji"';ctx.textAlign='center';ctx.fillText('🦷',0,-4)}else{poly([[-28,-5],[28,-5],[28,-56],[-28,-56]],o.type===1?'#b8745e':'#c7ae83');poly([[28,-5],[37,-16],[37,-65],[28,-56]],'#755851');poly([[-28,-56],[28,-56],[37,-65],[-19,-65]],'#efd4a8');text(mode===1?'SLIDE NỔI':['DEADLINE','DỰ ÁN','HỌP TIẾP'][o.type],0,-32,8,'#24313c');text(mode===1?'≋':['17:00','REVISE','+5 PHÚT'][o.type],0,-16,9,'#24313c')}ctx.restore()}
const p=project(visualLane,.1,w,h),bob=Math.sin(elapsed*12)*2;ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(p.x,p.y+10,29,9,0,0,7);ctx.fill();ctx.globalAlpha=invincible>0&&Math.floor(elapsed*13)%2===0?.45:1;if(mode===1){ctx.save();ctx.translate(p.x,p.y+bob);poly([[0,26],[-35,-10],[-28,-68],[0,-92],[28,-68],[35,-10]],'#d0a46d');poly([[0,14],[-24,-12],[-19,-59],[0,-77],[19,-59],[24,-12]],'#725846');runner(0,-22,.78);ctx.strokeStyle='#e8c591';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-10,-45);ctx.lineTo(44+Math.sin(elapsed*(3+stroke*10))*12,1);ctx.stroke();text('PHƯƠNG ÁN B',0,10,6,'#223540');ctx.restore()}else runner(p.x,p.y-jump*.6+bob,1);ctx.globalAlpha=1;
if(rain>0){ctx.strokeStyle=`rgba(190,216,225,${rain*.6})`;ctx.lineWidth=1;for(let i=0;i<125*rain;i++){const x=(i*83+elapsed*170)%w,y=(i*61+elapsed*510)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-7,y+16);ctx.stroke()}ctx.fillStyle=`rgba(5,17,31,${rain*.15})`;ctx.fillRect(0,0,w,h)}
if(distance>1510){const p=project(1,Math.max(.1,(1710-distance)/220),w,h);ctx.strokeStyle='#e2be7e';ctx.lineWidth=8*p.s;ctx.strokeRect(p.x-85*p.s,p.y-150*p.s,170*p.s,150*p.s);text('SUẤT CHIẾU 17.10',p.x,p.y-118*p.s,12*p.s,'#f6d59b')}}
function finish(){playing=false;meme.pause();if(noiseGain)noiseGain.gain.value=0;beep(784,.4);$('game').hidden=true;$('finish').hidden=false;window.scrollTo({top:0,behavior:'smooth'});for(let i=0;i<45;i++){const el=document.createElement('i');el.style.cssText=`position:fixed;pointer-events:none;width:5px;height:9px;background:#dfb77c;left:${Math.random()*100}vw;top:-15px;z-index:8;`;document.body.append(el);el.animate([{transform:'translateY(-10px)',opacity:1},{transform:`translateY(105vh) rotate(${Math.random()*800}deg)`,opacity:0}],{duration:2500+Math.random()*2000}).onfinish=()=>el.remove()}}
$('openGift').onclick=()=>{$('gift').hidden=false;$('openGift').hidden=true;$('gift').scrollIntoView({behavior:'smooth'})};$('plan').onclick=()=>{$('checklist').hidden=!$('checklist').hidden};
const photo=new URLSearchParams(location.search).get('photo');if(photo){const img=new Image();img.alt='Thanh Vy';img.onload=()=>$('portrait').replaceChildren(img);img.src=photo}
